// Package forge is what DevDesk asks of a code-hosting platform.
//
// It exists so a configuration context can target GitLab or GitHub — exactly
// one of the two, never both (§3.6). Everything above it speaks this
// vocabulary; only the backends know which SDK is underneath.
//
// # It is derived from what the code consumes, not from what an API offers
//
// Every method here answers a call site that exists today: the auth view wants
// the current user, the explorer browses and creates and deletes, the clone
// pipeline walks and builds URLs, the dashboard counts. Nothing was added
// because a forge happens to expose it. A method with no caller is a promise
// nobody checks, and two backends would honour it two different ways before
// anyone noticed.
//
// # A backend declares its shape
//
// The two forges differ in *words* and in *shapes*, and only the first is a
// presentation problem — Vocabulary handles those, and it is not in this
// package. A shape is what the abstraction can promise at all: how deep
// namespaces nest, which visibilities exist, whether a delete can be made
// permanent. Those are Shape, returned by the backend and never guessed from a
// URL — the registry `provider` field is the precedent (§3.8).
//
// # Identity is opaque; the path is not
//
// A namespace or a repository carries two strings. ID addresses it with the
// backend and means nothing outside: GitLab needs a number to create under a
// parent (CreateGroupOptions.ParentID is an *int64), GitHub addresses by owner.
// Path is the human one — `group/subgroup`, `owner/repo` — and it is what the
// clone URL, the display and GitLab's renamed-path deletion are built from.
//
// A caller that parses an ID is a caller bound to one forge. The type is a
// string so that arithmetic on it cannot be written.
//
// # A namespace and a repository are different types
//
// Not one node with a kind field. Only a namespace has children; only a
// repository has a pipeline status and a deletion schedule. Distinct types make
// "drill into a repository" unexpressible rather than forbidden by review —
// the same trade datatable's `Cell func(T) string` makes for Rule 122.
//
// The explorer still renders them in one table, and still holds its own
// TreeNode for what a *tree* needs — expanded, loading, parent, depth. Those
// are view state, and a forge has no opinion on them.
//
// # The backend paginates, and the caller never sees a page
//
// D34 was four copies of `PerPage: 100, Page: 1`, so a group with more than a
// hundred children was silently cut. A list returned here is complete or it is
// an error; there is no page to forget.
//
// # Every call takes a context
//
// The clone's discovery is cancellable and its clones are not (§3.16), which is
// a distinction the caller can only make if the reads take a context. Today
// every call passes context.Background(); that is what this fixes.
package forge

import "context"

// Forge is one code-hosting backend, bound to one host and one token.
//
// A consumer should declare the subset it needs rather than depend on this
// whole interface — Go resolves that at the consumer, so the backend does not
// have to be split. The dashboard wants DashboardStats and nothing else.
type Forge interface {
	// Shape reports what this backend can express. It is a value, not a
	// request: nothing about it depends on the network or on the token.
	Shape() Shape

	// CurrentUser is who the token belongs to. It is also the connection test:
	// authentication succeeded exactly when this returns.
	CurrentUser(ctx context.Context) (User, error)

	// RootNamespaces lists the top-level namespaces the user can see — GitLab's
	// top-level groups, GitHub's organisations. Complete, every page.
	RootNamespaces(ctx context.Context, opts BrowseOptions) ([]Namespace, error)

	// Children lists one namespace's direct children, complete.
	//
	// Direct, not recursive: the explorer drills one level at a time and the
	// clone walks levels itself, so a recursive listing would fetch what
	// neither asked for.
	Children(ctx context.Context, namespaceID string, opts BrowseOptions) (Children, error)

	// CreateNamespace creates a namespace, optionally under a parent. A backend
	// whose Shape refuses the requested depth returns an error rather than
	// creating it at the root.
	CreateNamespace(ctx context.Context, spec NewNamespace) (Namespace, error)

	// CreateRepository creates a repository inside a namespace.
	CreateRepository(ctx context.Context, spec NewRepository) (Repository, error)

	// InitialCommit writes the first commit of a repository — what a template
	// is applied by. It is separate from CreateRepository because a repository
	// is created whether or not a template was chosen.
	InitialCommit(ctx context.Context, repositoryID string, files []FileChange) error

	// DeleteNamespace deletes a namespace and everything under it.
	//
	// It takes the whole value rather than an ID because permanent deletion
	// needs both: GitLab schedules the deletion, which *renames* the namespace
	// to `<path>-deletion_scheduled-<id>`, and the second call addresses that
	// new path. A backend whose Shape says PermanentDelete is false returns an
	// error when asked for one, rather than deleting normally and reporting
	// success for something else.
	DeleteNamespace(ctx context.Context, ns Namespace, permanently bool) error

	// DeleteRepository deletes a repository. Same two-argument reasoning as
	// DeleteNamespace.
	DeleteRepository(ctx context.Context, repo Repository, permanently bool) error

	// DashboardStats fetches the dashboard's counters for one user.
	DashboardStats(ctx context.Context, user User) (DashboardStats, error)

	// CloneURL is the git URL for a repository. No network, no token: it is
	// built from the host, the path and the method, and the token travels
	// through git's environment rather than through the URL (§3.16).
	CloneURL(repo Repository, method CloneMethod) string

	// ChangeRequestsURL is the web page listing the user's merge or pull
	// requests, and AssignedIssuesURL the one listing their open issues.
	//
	// They are on the backend because the paths differ per forge and the views
	// used to build them with fmt.Sprintf against the configured URL — which is
	// a forge shape written in a view.
	// MergedCIConfig is the CI configuration the forge derives from the
	// repository: every include and component resolved, as the pipeline would
	// run. repoID addresses the repository the way the backend does, ref names
	// the branch — empty means the default one.
	//
	// It is the server's answer and not a local expansion, deliberately:
	// resolving includes here would mean re-implementing the forge's own CI
	// engine, and being wrong somewhere without knowing where.
	//
	// A backend whose Shape says MergedCIConfig is false returns an error
	// naming the reason. Callers gate on the shape rather than on the error —
	// the error is what a caller that forgot gets, not the way to ask.
	MergedCIConfig(ctx context.Context, repoID, ref string) (string, error)

	ChangeRequestsURL() string
	AssignedIssuesURL(user User) string
}

// Package gitlab is the GitLab backend of internal/forge.
//
// It is the only place in DevDesk that knows go-gitlab exists. Everything it
// exports is either forge's vocabulary or the constructor that binds a host and
// a token to it.
//
// # What it hides
//
// Pagination (D34), the numeric identifiers GitLab wants where a path will not
// do, the two-step permanent delete and its renamed path, and the mapping from
// GitLab's numeric access levels to a word. Each of those leaked into a view
// before this package existed, and each is the kind of thing a second forge
// would have contradicted quietly.
package gitlab

import (
	"context"
	"fmt"
	"log"
	"net/url"
	"strings"
	"sync"
	"time"

	gitlabclient "gitlab.com/gitlab-org/api/client-go"

	"github.com/anthnel/devdesk/internal/config"
	"github.com/anthnel/devdesk/internal/forge"
)

// Forge is a GitLab instance, bound to one host and one token.
type Forge struct {
	client *gitlabclient.Client
	// mu guards user, the memoised answer to CurrentUser. The clone pipeline
	// calls into the backend from several goroutines, so this is a real race
	// rather than a theoretical one.
	mu   sync.Mutex
	user *forge.User
	// baseURL is the host as the user configured it, trailing slash removed.
	// The SDK holds its own API base; this one builds clone URLs and web links,
	// which are not API paths.
	baseURL string
}

var _ forge.Forge = (*Forge)(nil)

// New binds a GitLab instance to a token.
func New(baseURL, token string) (*Forge, error) {
	client, err := gitlabclient.NewClient(token, gitlabclient.WithBaseURL(baseURL))
	if err != nil {
		return nil, err
	}
	return NewWithClient(client, baseURL), nil
}

// NewWithClient wraps a client that already exists, or none at all.
//
// A nil client is legitimate: CloneURL, ChangeRequestsURL and AssignedIssuesURL
// are built from the host and touch nothing, so they answer without a session.
func NewWithClient(client *gitlabclient.Client, baseURL string) *Forge {
	return &Forge{client: client, baseURL: strings.TrimSuffix(baseURL, "/")}
}

// Shape is GitLab's, and it is a constant: nothing about it depends on the
// instance or on the token.
//
// It delegates to forge.ShapeFor so there is one table rather than two. A shape
// is a property of the platform, and the configuration view needs it before any
// session exists — this method is for a consumer that holds a session and does
// not know the type.
func (f *Forge) Shape() forge.Shape {
	return forge.ShapeFor(config.ForgeGitLab)
}

// CurrentUser is who the token belongs to, and the connection test with it.
// It is memoised, and that is not an optimisation. Every decorated listing
// needs the caller's id for its role lookups; asking the host each time would
// add one request per listing that the pre-abstraction code did not make,
// because it took the id from a session the view was already holding. Who a
// token belongs to does not change for the life of a session.
func (f *Forge) CurrentUser(ctx context.Context) (forge.User, error) {
	f.mu.Lock()
	if f.user != nil {
		defer f.mu.Unlock()
		return *f.user, nil
	}
	f.mu.Unlock()

	user, _, err := f.client.Users.CurrentUser(gitlabclient.WithContext(ctx))
	if err != nil {
		return forge.User{}, err
	}
	resolved := forge.User{
		ID:       fmt.Sprint(user.ID),
		Username: user.Username,
		Name:     user.Name,
	}

	f.mu.Lock()
	f.user = &resolved
	f.mu.Unlock()
	return resolved, nil
}

// CloneURL builds the git URL. No network and no token: the token travels
// through git's environment, never in the URL (§3.16).
func (f *Forge) CloneURL(repo forge.Repository, method forge.CloneMethod) string {
	if method == forge.CloneSSH {
		host := strings.TrimPrefix(strings.TrimPrefix(f.baseURL, "https://"), "http://")
		return fmt.Sprintf("git@%s:%s.git", host, repo.Path)
	}
	return fmt.Sprintf("%s/%s.git", f.baseURL, repo.Path)
}

// ChangeRequestsURL is GitLab's merge request dashboard.
func (f *Forge) ChangeRequestsURL() string {
	return f.baseURL + "/dashboard/merge_requests"
}

// AssignedIssuesURL is the issue dashboard filtered to one assignee.
//
// The username is escaped rather than interpolated raw: it reaches this from
// the API, but a URL built by concatenation is how a query parameter ends up
// meaning something else, and nothing about the call site says the value is
// safe.
func (f *Forge) AssignedIssuesURL(user forge.User) string {
	q := url.Values{
		"sort":                {"created_date"},
		"state":               {"opened"},
		"assignee_username[]": {user.Username},
	}
	return f.baseURL + "/dashboard/issues?" + q.Encode()
}

// roleName turns a GitLab access level into the word forge.Namespace.Role
// promises. It is the mapping TreeNode.AccessLevelName held, moved to the only
// place that knows what a 40 means.
//
// Zero is "not known" and returns the empty string — not "Guest". A role the
// backend could not read is not the lowest role there is.
func roleName(level int) string {
	switch {
	case level >= 50:
		return "Owner"
	case level >= 40:
		return "Maintainer"
	case level >= 30:
		return "Developer"
	case level >= 20:
		return "Reporter"
	case level >= 10:
		return "Guest"
	default:
		return ""
	}
}

// namespaceID renders a GitLab numeric ID as the opaque string forge uses.
func namespaceID(id int64) string { return fmt.Sprint(id) }

// numericID reads back what namespaceID wrote.
//
// Only this package may do it — that is the package doc's rule, and the reason
// forge.Namespace.ID is a string is so that no caller outside can. GitLab needs
// the number in two places where a path is not accepted: CreateGroupOptions
// .ParentID and CreateProjectOptions.NamespaceID are both *int64.
func numericID(id string) (int64, error) {
	var n int64
	if _, err := fmt.Sscanf(id, "%d", &n); err != nil {
		return 0, fmt.Errorf("not a GitLab id: %q", id)
	}
	return n, nil
}

// deletionPath is what GitLab renames a group or project to when a deletion is
// scheduled. The permanent removal addresses that name, not the original.
func deletionPath(path string, id int64) string {
	return fmt.Sprintf("%s-deletion_scheduled-%d", path, id)
}

// propagationDelay is the pause between scheduling a deletion and asking for
// the permanent removal.
//
// It was in the code being moved, undocumented. It is kept because removing it
// would be an unrelated behaviour change inside a refactor that promises none —
// not because 500 ms is known to be the right number.
const propagationDelay = 500 * time.Millisecond

// MergedCIConfig is the pipeline as GitLab resolves it: every `include` and
// every component expanded server-side, which is what a plumber finding is
// actually about (§3.42).
//
// The lint endpoint is the only thing that answers this. Its result carries the
// resolved document and the transitive include graph, and neither is derivable
// from the repository alone — a single `include:` in a fifteen-line file
// resolves to fifteen includes and twenty-one jobs on a measured example.
//
// A configuration the server refuses is **not** an error here: the document is
// what the user came to read, and a lint failure is often precisely why. The
// errors go to the log, the YAML comes back if there is one, and an empty
// document is the one case that fails — there is nothing to show.
func (f *Forge) MergedCIConfig(ctx context.Context, repoID, ref string) (string, error) {
	opts := &gitlabclient.ProjectLintOptions{}
	if ref != "" {
		opts.Ref = gitlabclient.Ptr(ref)
	}
	result, _, err := f.client.Validate.ProjectLint(repoID, opts, gitlabclient.WithContext(ctx))
	if err != nil {
		return "", fmt.Errorf("resolve CI configuration for %s: %w", repoID, err)
	}
	if !result.Valid {
		log.Printf("WARN [forge/gitlab] %s: the resolved CI configuration is invalid: %s",
			repoID, strings.Join(result.Errors, "; "))
	}
	if result.MergedYaml == "" {
		return "", fmt.Errorf("resolve CI configuration for %s: the server returned no document", repoID)
	}
	return result.MergedYaml, nil
}

