11	// perPage is what every list endpoint asks for. GitLab caps it at 100.
12	const perPage = 100
13	
14	// listAll walks every page of a list endpoint and returns the lot (D34).
15	//
16	// Each caller used to pass `Page: 1` and keep only what came back, so a group
17	// with more than perPage subgroups or projects was silently cut: the explorer
18	// showed fewer than it had and a recursive clone skipped repositories without
19	// saying so. The loop lives here rather than at each call site because four
20	// copies of it is how one of them would end up wrong.
21	//
22	// opts is the caller's embedded ListOptions, mutated between calls, so the
23	// fetch closure sees the new page without the caller rebuilding its options.
24	func listAll[T any](opts *gitlabclient.ListOptions, fetch func() ([]T, *gitlabclient.Response, error)) ([]T, error) {
25		opts.PerPage = perPage
26		opts.Page = 1
27	
28		var all []T
29		for {
30			page, resp, err := fetch()
31			if err != nil {
32				return nil, err
33			}
34			all = append(all, page...)
35	
36			// NextPage is 0 on the last page. Comparing against the page just
37			// fetched rather than against 0 alone also stops a server that keeps
38			// pointing back at it, which would otherwise spin for ever — and it is
39			// a bound that cannot cut a legitimate response short, which a page
40			// limit would be.
41			if resp == nil || resp.NextPage <= opts.Page {
42				return all, nil
43			}
44			opts.Page = resp.NextPage
45		}
46	}
47	
48	// RootNamespaces lists the top-level groups, every page.
49	func (f *Forge) RootNamespaces(ctx context.Context, opts forge.BrowseOptions) ([]forge.Namespace, error) {
50		listOpts := &gitlabclient.ListGroupsOptions{TopLevelOnly: gitlabclient.Ptr(true)}
51		groups, err := listAll(&listOpts.ListOptions, func() ([]*gitlabclient.Group, *gitlabclient.Response, error) {
52			return f.client.Groups.ListGroups(listOpts, gitlabclient.WithContext(ctx))
53		})
54		if err != nil {
55			return nil, err
56		}
57		return f.namespaces(ctx, groups, f.decoratingAs(ctx, opts)), nil
58	}
59	
60	// decoratingAs resolves the current user once per listing, or reports 0 when
61	// the listing asks for no decoration.
62	//
63	// Once per listing, not once per row: the role lookups need the caller's ID,
64	// and asking for it inside the loop would add one request per group — which is
65	// how a decoration that already costs two calls per repository would have come
66	// to cost three.
67	func (f *Forge) decoratingAs(ctx context.Context, opts forge.BrowseOptions) int64 {
68		if !opts.Decorated {
69			return 0
70		}
71		user, err := f.CurrentUser(ctx)
72		if err != nil {
73			return 0
74		}
75		uid, err := numericID(user.ID)
76		if err != nil {
77			return 0
78		}
79		return uid
80	}
