83	// each.
84	//
85	// Direct, not recursive: the explorer drills one level at a time and the clone
86	// walks levels itself.
87	func (f *Forge) Children(ctx context.Context, namespaceID string, opts forge.BrowseOptions) (forge.Children, error) {
88		subOpts := &gitlabclient.ListSubGroupsOptions{}
89		subgroups, err := listAll(&subOpts.ListOptions, func() ([]*gitlabclient.Group, *gitlabclient.Response, error) {
90			return f.client.Groups.ListSubGroups(namespaceID, subOpts, gitlabclient.WithContext(ctx))
91		})
92		if err != nil {
93			return forge.Children{}, err
94		}
95	
96		projOpts := &gitlabclient.ListGroupProjectsOptions{}
97		if !opts.IncludeArchived {
98			projOpts.Archived = gitlabclient.Ptr(false)
99		}
100		projects, err := listAll(&projOpts.ListOptions, func() ([]*gitlabclient.Project, *gitlabclient.Response, error) {
101			return f.client.Groups.ListGroupProjects(namespaceID, projOpts, gitlabclient.WithContext(ctx))
102		})
103		if err != nil {
104			return forge.Children{}, err
105		}
106	
107		uid := f.decoratingAs(ctx, opts)
108		return forge.Children{
109			Namespaces:   f.namespaces(ctx, subgroups, uid),
110			Repositories: f.repositories(ctx, projects, uid),
111		}, nil
112	}
113	
114	// namespaces converts groups, decorating each with the caller's role when uid
115	// is non-zero.
116	func (f *Forge) namespaces(ctx context.Context, groups []*gitlabclient.Group, uid int64) []forge.Namespace {
117		out := make([]forge.Namespace, 0, len(groups))
118		for _, g := range groups {
119			ns := forge.Namespace{
120				ID:         namespaceID(g.ID),
121				Path:       g.FullPath,
122				Name:       g.Name,
123				Visibility: string(g.Visibility),
124				CreatedAt:  g.CreatedAt,
125				WebURL:     g.WebURL,
126			}
127			if uid != 0 {
128				ns.Role = f.groupRole(ctx, g.ID, uid)
129			}
130			out = append(out, ns)
131		}
132		return out
133	}
134	
135	// repositories converts projects, decorating each with the caller's role and
136	// the last pipeline status when asked.
137	//
138	// The decoration is two extra requests **per project**, which is why it is an
139	// option and not a default: a two-hundred-repository group costs 400 calls for
140	// a CI badge and a role that a clone never reads.
141	func (f *Forge) repositories(ctx context.Context, projects []*gitlabclient.Project, uid int64) []forge.Repository {
142		out := make([]forge.Repository, 0, len(projects))
143		for _, p := range projects {
144			repo := forge.Repository{
145				ID:                namespaceID(int64(p.ID)),
146				Path:              p.PathWithNamespace,
147				Name:              p.Name,
148				Visibility:        string(p.Visibility),
149				CreatedAt:         p.CreatedAt,
150				LastActivityAt:    p.LastActivityAt,
151				WebURL:            p.WebURL,
152				DeletionScheduled: p.MarkedForDeletionOn != nil,
153			}
154			if uid != 0 {
155				repo.Role = f.projectRole(ctx, int64(p.ID), uid)
156				repo.CIStatus = f.lastPipelineStatus(ctx, int64(p.ID))
157			}
158			out = append(out, repo)
159		}
160		return out
161	}
162	
163	// groupRole is the caller's humanised role in a group, empty when it cannot be
164	// read. A decoration that fails is not worth failing the listing for: the
165	// explorer would show nothing rather than a column short.
166	func (f *Forge) groupRole(ctx context.Context, groupID, uid int64) string {
167		member, _, err := f.client.GroupMembers.GetInheritedGroupMember(int(groupID), uid, gitlabclient.WithContext(ctx))
168		if err != nil {
169			return ""
170		}
171		return roleName(int(member.AccessLevel))
172	}
173	
174	// projectRole is the caller's humanised role in a project.
175	func (f *Forge) projectRole(ctx context.Context, projectID, uid int64) string {
176		member, _, err := f.client.ProjectMembers.GetInheritedProjectMember(int(projectID), uid, gitlabclient.WithContext(ctx))
177		if err != nil {
178			return ""
179		}
180		return roleName(int(member.AccessLevel))
181	}
182	
183	// lastPipelineStatus is the most recent pipeline's status, empty when there is
184	// none or it cannot be read.
185	func (f *Forge) lastPipelineStatus(ctx context.Context, projectID int64) string {
186		pipelines, _, err := f.client.Pipelines.ListProjectPipelines(projectID, &gitlabclient.ListProjectPipelinesOptions{
187			ListOptions: gitlabclient.ListOptions{PerPage: 1, Page: 1},
188		}, gitlabclient.WithContext(ctx))
189		if err != nil || len(pipelines) == 0 {
190			return ""
191		}
192		return pipelines[0].Status
193	}
