package gitlab

import (
	"context"
	"fmt"
	"time"

	gitlabclient "gitlab.com/gitlab-org/api/client-go"

	"github.com/anthnel/devdesk/internal/forge"
)

// CreateNamespace creates a group, optionally under a parent.
func (f *Forge) CreateNamespace(ctx context.Context, spec forge.NewNamespace) (forge.Namespace, error) {
	opts := &gitlabclient.CreateGroupOptions{
		Name:        gitlabclient.Ptr(spec.Name),
		Path:        gitlabclient.Ptr(spec.Slug),
		Description: gitlabclient.Ptr(spec.Description),
		Visibility:  gitlabclient.Ptr(gitlabclient.VisibilityValue(spec.Visibility)),
	}

	// ParentID is one of the two places a path will not do — see numericID.
	if spec.ParentID != "" {
		parent, err := numericID(spec.ParentID)
		if err != nil {
			return forge.Namespace{}, err
		}
		opts.ParentID = gitlabclient.Ptr(parent)
	}

	group, _, err := f.client.Groups.CreateGroup(opts, gitlabclient.WithContext(ctx))
	if err != nil {
		return forge.Namespace{}, err
	}
	return f.namespaces(ctx, []*gitlabclient.Group{group}, 0)[0], nil
}

// CreateRepository creates a project inside a namespace.
func (f *Forge) CreateRepository(ctx context.Context, spec forge.NewRepository) (forge.Repository, error) {
	opts := &gitlabclient.CreateProjectOptions{
		Name:        gitlabclient.Ptr(spec.Name),
		Path:        gitlabclient.Ptr(spec.Slug),
		Description: gitlabclient.Ptr(spec.Description),
		Visibility:  gitlabclient.Ptr(gitlabclient.VisibilityValue(spec.Visibility)),
	}

	if spec.NamespaceID != "" {
		ns, err := numericID(spec.NamespaceID)
		if err != nil {
			return forge.Repository{}, err
		}
		opts.NamespaceID = gitlabclient.Ptr(ns)
	}

	project, _, err := f.client.Projects.CreateProject(opts, gitlabclient.WithContext(ctx))
	if err != nil {
		return forge.Repository{}, err
	}
	return f.repositories(ctx, []*gitlabclient.Project{project}, 0)[0], nil
}

// InitialCommit writes the first commit of a repository — what a template is
// applied by.
func (f *Forge) InitialCommit(ctx context.Context, repositoryID string, files []forge.FileChange) error {
	actions := make([]*gitlabclient.CommitActionOptions, len(files))
	for i, file := range files {
		actions[i] = &gitlabclient.CommitActionOptions{
			Action:   gitlabclient.Ptr(gitlabclient.FileActionValue(file.Action)),
			FilePath: gitlabclient.Ptr(file.Path),
			Content:  gitlabclient.Ptr(file.Content),
		}
	}

	opts := &gitlabclient.CreateCommitOptions{
		Branch:        gitlabclient.Ptr("main"),
		CommitMessage: gitlabclient.Ptr("Initial commit from template"),
		Actions:       actions,
	}

	_, _, err := f.client.Commits.CreateCommit(repositoryID, opts, gitlabclient.WithContext(ctx))
	return err
}

// DeleteNamespace deletes a group and everything under it.
//
// A permanent deletion is two calls, and the second does not address what the
// first did: GitLab schedules the deletion by *renaming* the group to
// `<path>-deletion_scheduled-<id>`, so the removal is asked for by that new
// name. Getting it from the value rather than from an ID is why the interface
// takes the whole Namespace.
func (f *Forge) DeleteNamespace(ctx context.Context, ns forge.Namespace, permanently bool) error {
	_, err := f.client.Groups.DeleteGroup(ns.ID, nil, gitlabclient.WithContext(ctx))
	if err != nil || !permanently {
		return err
	}

	id, err := numericID(ns.ID)
	if err != nil {
		return err
	}
	renamed := deletionPath(ns.Path, id)

	opts := &gitlabclient.DeleteGroupOptions{
		PermanentlyRemove: gitlabclient.Ptr(true),
		FullPath:          gitlabclient.Ptr(renamed),
	}
	if _, err := f.client.Groups.DeleteGroup(renamed, opts, gitlabclient.WithContext(ctx)); err != nil {
		return err
	}

	time.Sleep(propagationDelay)
	return nil
}

// DeleteRepository deletes a project. Same two-call reasoning as
// DeleteNamespace.
func (f *Forge) DeleteRepository(ctx context.Context, repo forge.Repository, permanently bool) error {
	_, err := f.client.Projects.DeleteProject(repo.ID, nil, gitlabclient.WithContext(ctx))
	if err != nil || !permanently {
		return err
	}

	id, err := numericID(repo.ID)
	if err != nil {
		return err
	}
	renamed := deletionPath(repo.Path, id)

	opts := &gitlabclient.DeleteProjectOptions{
		PermanentlyRemove: gitlabclient.Ptr(true),
		FullPath:          gitlabclient.Ptr(renamed),
	}
	if _, err := f.client.Projects.DeleteProject(renamed, opts, gitlabclient.WithContext(ctx)); err != nil {
		return err
	}

	time.Sleep(propagationDelay)
	return nil
}

// DashboardStats fetches the five counters.
//
// Each is a separate request and each can fail on its own, so each is filled
// only when its request succeeded. A failed one stays nil — see
// forge.DashboardStats and D52: the int this replaced left a zero that the
// dashboard rendered exactly as it renders "you have none".
//
// It returns no error for the same reason: four counters out of five is a
// better dashboard than none, and which one is missing is on the field rather
// than in a message.
func (f *Forge) DashboardStats(ctx context.Context, user forge.User) (forge.DashboardStats, error) {
	uid, err := numericID(user.ID)
	if err != nil {
		return forge.DashboardStats{}, fmt.Errorf("dashboard stats: %w", err)
	}

	var stats forge.DashboardStats
	one := gitlabclient.ListOptions{PerPage: 1}

	// TotalItems comes from the X-Total header, so one item per page is enough
	// to learn how many there are.
	if _, resp, err := f.client.MergeRequests.ListMergeRequests(&gitlabclient.ListMergeRequestsOptions{
		State:       gitlabclient.Ptr("opened"),
		AssigneeID:  gitlabclient.AssigneeID(uid),
		ListOptions: one,
	}, gitlabclient.WithContext(ctx)); err == nil {
		stats.AssignedChangeRequests = forge.Count(int(resp.TotalItems))
	}

	if _, resp, err := f.client.MergeRequests.ListMergeRequests(&gitlabclient.ListMergeRequestsOptions{
		State:       gitlabclient.Ptr("opened"),
		ReviewerID:  gitlabclient.ReviewerID(uid),
		ListOptions: one,
	}, gitlabclient.WithContext(ctx)); err == nil {
		stats.ReviewChangeRequests = forge.Count(int(resp.TotalItems))
	}

	if _, resp, err := f.client.Issues.ListIssues(&gitlabclient.ListIssuesOptions{
		State:       gitlabclient.Ptr("opened"),
		AssigneeID:  gitlabclient.AssigneeID(uid),
		ListOptions: one,
	}, gitlabclient.WithContext(ctx)); err == nil {
		stats.AssignedIssues = forge.Count(int(resp.TotalItems))
	}

	if _, resp, err := f.client.Projects.ListProjects(&gitlabclient.ListProjectsOptions{
		Membership:  gitlabclient.Ptr(true),
		ListOptions: one,
	}, gitlabclient.WithContext(ctx)); err == nil {
		stats.Repositories = forge.Count(int(resp.TotalItems))
	}

	if _, resp, err := f.client.Groups.ListGroups(&gitlabclient.ListGroupsOptions{
		ListOptions: one,
	}, gitlabclient.WithContext(ctx)); err == nil {
		stats.Namespaces = forge.Count(int(resp.TotalItems))
	}

	return stats, nil
}

// Package github is the GitHub backend of internal/forge.
//
// It is the only place in DevDesk that knows go-github exists, as its GitLab
// sibling is the only place that knows go-gitlab.
//
// # What it does not do, and says so
//
// GitHub has no API for creating or deleting an **organisation**, and no grace
// period a delete could bypass. The interface expects a backend to refuse what
// its Shape says it cannot express rather than to do something adjacent and
// report success — so both come back as errors naming the reason, and the
// permanent-delete checkbox is out of reach because `Shape.PermanentDelete` is
// false.
//
// # Identity is the path
//
// forge.Namespace.ID is opaque, which lets each backend pick what addresses an
// object. GitLab needs a number in two places; GitHub needs `owner` and
// `owner/repo` everywhere, so here ID and Path are the same string. Nothing
// outside this package may notice.
package github

import (
	"context"
	"errors"
	"fmt"
	"net/url"
	"strings"
	"sync"

	gh "github.com/google/go-github/v68/github"

	"github.com/anthnel/devdesk/internal/config"
	"github.com/anthnel/devdesk/internal/forge"
)

// Forge is a GitHub instance — github.com or an Enterprise Server — bound to
// one token.
type Forge struct {
	client *gh.Client
	// baseURL is the *web* host as the user configured it. The SDK holds its
	// own API base, which on Enterprise is a different path; this one builds
	// clone URLs and browser links.
	baseURL string

	mu   sync.Mutex
	user *forge.User
}

var _ forge.Forge = (*Forge)(nil)

// New binds a GitHub instance to a token.
//
// A host other than github.com is taken as GitHub Enterprise Server, whose API
// lives under /api/v3/ — WithEnterpriseURLs appends that, so the configured URL
// stays the web host the user typed and the one clone URLs are built from.
func New(baseURL, token string) (*Forge, error) {
	client := gh.NewClient(nil).WithAuthToken(token)

	trimmed := strings.TrimSuffix(baseURL, "/")
	if !isDotCom(trimmed) && trimmed != "" {
		enterprise, err := client.WithEnterpriseURLs(trimmed, trimmed)
		if err != nil {
			return nil, fmt.Errorf("github enterprise URL: %w", err)
		}
		client = enterprise
	}

	return &Forge{client: client, baseURL: trimmed}, nil
}

// NewWithClient wraps a client that already exists, or none at all. A nil
// client is legitimate: the URL helpers touch nothing.
func NewWithClient(client *gh.Client, baseURL string) *Forge {
	return &Forge{client: client, baseURL: strings.TrimSuffix(baseURL, "/")}
}

// isDotCom reports whether a URL names the public instance.
func isDotCom(rawURL string) bool {
	host := strings.TrimPrefix(strings.TrimPrefix(rawURL, "https://"), "http://")
	host, _, _ = strings.Cut(host, "/")
	return host == "" || host == "github.com" || host == "www.github.com"
}

// Shape delegates, so the platform's capabilities are declared once (§3.6
// step 6). GitHub's are the interesting half of the abstraction: no nesting, no
// `internal`, no permanent delete.
func (f *Forge) Shape() forge.Shape {
	return forge.ShapeFor(config.ForgeGitHub)
}

// CurrentUser is who the token belongs to, and the connection test with it.
//
// Memoised for its GitLab sibling's reason: every decorated listing needs the
// caller's login for its role lookups, and asking the host each time would add
// a request per listing.
func (f *Forge) CurrentUser(ctx context.Context) (forge.User, error) {
	f.mu.Lock()
	if f.user != nil {
		defer f.mu.Unlock()
		return *f.user, nil
	}
	f.mu.Unlock()

	user, _, err := f.client.Users.Get(ctx, "")
	if err != nil {
		return forge.User{}, err
	}

	// The login, not the numeric id: it is what every other call addresses a
	// user by, and forge.User.ID is opaque precisely so a backend can choose.
	resolved := forge.User{
		ID:       user.GetLogin(),
		Username: user.GetLogin(),
		Name:     user.GetName(),
	}

	f.mu.Lock()
	f.user = &resolved
	f.mu.Unlock()
	return resolved, nil
}

// CloneURL builds the git URL from the web host, the path and the method.
func (f *Forge) CloneURL(repo forge.Repository, method forge.CloneMethod) string {
	base := f.webBase()
	if method == forge.CloneSSH {
		host := strings.TrimPrefix(strings.TrimPrefix(base, "https://"), "http://")
		return fmt.Sprintf("git@%s:%s.git", host, repo.Path)
	}
	return fmt.Sprintf("%s/%s.git", base, repo.Path)
}

// ChangeRequestsURL is GitHub's pull request dashboard.
func (f *Forge) ChangeRequestsURL() string { return f.webBase() + "/pulls" }

// AssignedIssuesURL is the issue dashboard filtered to one assignee.
//
// GitHub has no per-assignee path, so the filter goes in the `q` search
// parameter — which is exactly why it is escaped rather than concatenated.
func (f *Forge) AssignedIssuesURL(user forge.User) string {
	q := url.Values{"q": {"is:open is:issue assignee:" + user.Username}}
	return f.webBase() + "/issues?" + q.Encode()
}

// webBase is the host browser links and clone URLs are built from. An empty
// configured URL means github.com, which is the only host that has a default.
func (f *Forge) webBase() string {
	if f.baseURL == "" {
		return "https://github.com"
	}
	return f.baseURL
}

// MergedCIConfig is refused: GitHub has no equivalent.
//
// A workflow's `uses:` is resolved by the runner when the job starts, so there
// is no endpoint that hands back an expanded workflow — and answering with the
// raw `.github/workflows/*.yml` would report a distinction the platform does
// not make, which is the argument that already refuses CreateNamespace and a
// permanent delete here.
//
// Shape().MergedCIConfig is false, so a caller that gates on the shape never
// reaches this. It exists for the one that forgot.
func (f *Forge) MergedCIConfig(_ context.Context, _, _ string) (string, error) {
	return "", errors.New("GitHub resolves a workflow's `uses:` when the runner starts it, so there is no resolved configuration to fetch")
}

package github

import (
	"context"
	"strings"

	gh "github.com/google/go-github/v68/github"

	"github.com/anthnel/devdesk/internal/forge"
)

// perPage is what every list endpoint asks for. GitHub caps it at 100.
const perPage = 100

// listAll walks every page and returns the lot — D34's rule, applied to the
// second backend before it can go wrong here too.
//
// GitHub paginates by Link header, which go-github surfaces as
// Response.NextPage, 0 on the last page. The guard against a server that keeps
// pointing at the page just served is the GitLab backend's, for the same
// reason: it cannot cut a legitimate response short, which a page cap would.
func listAll[T any](fetch func(opts *gh.ListOptions) ([]T, *gh.Response, error)) ([]T, error) {
	opts := &gh.ListOptions{PerPage: perPage, Page: 1}

	var all []T
	for {
		page, resp, err := fetch(opts)
		if err != nil {
			return nil, err
		}
		all = append(all, page...)

		if resp == nil || resp.NextPage <= opts.Page {
			return all, nil
		}
		opts.Page = resp.NextPage
	}
}

// RootNamespaces lists the user's own account, then the organisations the token
// can see.
//
// **The personal account comes first, and leaving it out was a bug.** The first
// version of this excluded it, reasoning that "a personal namespace is not an
// organisation: it cannot be created or deleted, so listing it would put a row
// in the tree that half the actions refuse". That is wrong on its own terms —
// *no* GitHub organisation can be created or deleted through the API, so the
// personal account is not less capable than an organisation but **more**: it is
// the one namespace where a repository can be created and deleted.
//
// The cost of the mistake was the common case. A personal GitHub account
// belongs to no organisation, so the explorer opened empty and said so, on the
// account shape most people have.
func (f *Forge) RootNamespaces(ctx context.Context, opts forge.BrowseOptions) ([]forge.Namespace, error) {
	orgs, err := listAll(func(page *gh.ListOptions) ([]*gh.Organization, *gh.Response, error) {
		return f.client.Organizations.List(ctx, "", page)
	})
	if err != nil {
		return nil, err
	}

	namespaces := f.namespaces(ctx, orgs, f.decoratingAs(ctx, opts))

	// The personal namespace is prepended rather than appended: it is where a
	// solo account's repositories are, and burying it under a list of
	// organisations would hide the only row half of them have.
	if personal, ok := f.personalNamespace(ctx); ok {
		return append([]forge.Namespace{personal}, namespaces...), nil
	}
	return namespaces, nil
}

// personalNamespace is the signed-in user as a namespace.
//
// **Its ID is the empty string, and that is the interface's own word for it**:
// forge.NewRepository.NamespaceID documents "empty means the user's own
// namespace", and go-github's Repositories.Create takes exactly that for the
// `org` argument. Passing the login instead would 404 — GitHub refuses to treat
// a user as an organisation, which is the same distinction this row exists to
// carry.
//
// A user that cannot be read yields no row rather than an error: the
// organisations are still worth showing, and CurrentUser is memoised so this
// costs nothing after the first call.
func (f *Forge) personalNamespace(ctx context.Context) (forge.Namespace, bool) {
	user, err := f.CurrentUser(ctx)
	if err != nil {
		return forge.Namespace{}, false
	}
	return forge.Namespace{
		ID:     "",
		Path:   user.Username,
		Name:   firstNonEmpty(user.Name, user.Username),
		WebURL: f.webBase() + "/" + user.Username,
		// Owner without asking: it is the account the token belongs to.
		Role: "Owner",
	}, true
}

// Children lists an organisation's repositories.
//
// Never namespaces: an organisation does not hold another one, which is what a
// MaxNamespaceDepth of 1 declares. The empty slice is the answer, not a missing
// feature.
func (f *Forge) Children(ctx context.Context, namespaceID string, opts forge.BrowseOptions) (forge.Children, error) {
	repos, err := f.repositoriesOf(ctx, namespaceID)
	if err != nil {
		return forge.Children{}, err
	}

	// GitHub has no "exclude archived" filter, so they are dropped after the
	// fact. It costs nothing extra: they were in the page either way.
	if !opts.IncludeArchived {
		kept := repos[:0]
		for _, repo := range repos {
			if !repo.GetArchived() {
				kept = append(kept, repo)
			}
		}
		repos = kept
	}

	return forge.Children{Repositories: f.repositories(ctx, repos, f.decoratingAs(ctx, opts))}, nil
}

// repositoriesOf lists what a namespace holds, every page.
//
// The empty namespace is the signed-in user's own, and it takes a different
// endpoint: /user/repos rather than /orgs/{org}/repos. `Affiliation: owner`
// keeps it to what the user owns — without it the list also carries every
// repository they collaborate on, which belongs under whoever owns it and would
// appear twice in a tree that shows both.
func (f *Forge) repositoriesOf(ctx context.Context, namespaceID string) ([]*gh.Repository, error) {
	if namespaceID == "" {
		opts := &gh.RepositoryListByAuthenticatedUserOptions{Affiliation: "owner"}
		return listAll(func(page *gh.ListOptions) ([]*gh.Repository, *gh.Response, error) {
			opts.ListOptions = *page
			return f.client.Repositories.ListByAuthenticatedUser(ctx, opts)
		})
	}

	opts := &gh.RepositoryListByOrgOptions{Type: "all"}
	return listAll(func(page *gh.ListOptions) ([]*gh.Repository, *gh.Response, error) {
		opts.ListOptions = *page
		return f.client.Repositories.ListByOrg(ctx, namespaceID, opts)
	})
}

// decoratingAs resolves the caller's login once per listing, or "" when no
// decoration was asked for. Once per listing, not once per row — the same cost
// argument as the GitLab backend's.
func (f *Forge) decoratingAs(ctx context.Context, opts forge.BrowseOptions) string {
	if !opts.Decorated {
		return ""
	}
	user, err := f.CurrentUser(ctx)
	if err != nil {
		return ""
	}
	return user.Username
}

// namespaces converts organisations.
func (f *Forge) namespaces(ctx context.Context, orgs []*gh.Organization, login string) []forge.Namespace {
	out := make([]forge.Namespace, 0, len(orgs))
	for _, org := range orgs {
		created := org.GetCreatedAt().Time
		ns := forge.Namespace{
			ID:     org.GetLogin(),
			Path:   org.GetLogin(),
			Name:   firstNonEmpty(org.GetName(), org.GetLogin()),
			WebURL: f.webBase() + "/" + org.GetLogin(),
			// An organisation has no visibility of its own on GitHub — its
			// repositories do. Left empty rather than invented.
			CreatedAt: &created,
		}
		if login != "" {
			ns.Role = f.orgRole(ctx, org.GetLogin(), login)
		}
		out = append(out, ns)
	}
	return out
}

// repositories converts repositories, decorating each with the caller's role
// and the last workflow run when asked.
//
// The decoration is two extra requests per repository here too, and the clone's
// walk asks for none of it.
func (f *Forge) repositories(ctx context.Context, repos []*gh.Repository, login string) []forge.Repository {
	out := make([]forge.Repository, 0, len(repos))
	for _, repo := range repos {
		created, pushed := repo.GetCreatedAt().Time, repo.GetPushedAt().Time
		full := repo.GetFullName()

		converted := forge.Repository{
			ID:             full,
			Path:           full,
			Name:           repo.GetName(),
			Visibility:     visibilityOf(repo),
			CreatedAt:      &created,
			LastActivityAt: &pushed,
			WebURL:         repo.GetHTMLURL(),
			// GitHub deletes at once, so a repository is never *scheduled* for
			// deletion. Always false, and Shape.PermanentDelete says why.
			DeletionScheduled: false,
		}
		if login != "" {
			converted.Role = roleName(repo.GetPermissions())
			converted.CIStatus = f.lastWorkflowStatus(ctx, repo.GetOwner().GetLogin(), repo.GetName())
		}
		out = append(out, converted)
	}
	return out
}

// visibilityOf reads a repository's visibility.
//
// Visibility is the field Enterprise populates with `internal`; Private is the
// older boolean github.com always sets. Reading the first and falling back to
// the second is what keeps an Enterprise `internal` from being reported as
// `private` — a visibility this platform's Shape does not offer for creation,
// but which an Enterprise instance really has.
func visibilityOf(repo *gh.Repository) string {
	if v := repo.GetVisibility(); v != "" {
		return v
	}
	if repo.GetPrivate() {
		return "private"
	}
	return "public"
}

// roleName turns GitHub's permission flags into the word
// forge.Repository.Role promises.
//
// They arrive as a set of booleans rather than as a level, so the mapping reads
// most-privileged first. Nothing means the permissions were not returned, which
// is not the same as "no access" — hence the empty string, as on GitLab.
func roleName(perms map[string]bool) string {
	switch {
	case perms["admin"]:
		return "Owner"
	case perms["maintain"]:
		return "Maintainer"
	case perms["push"]:
		return "Developer"
	case perms["triage"]:
		return "Reporter"
	case perms["pull"]:
		return "Guest"
	default:
		return ""
	}
}

// orgRole is the caller's humanised role in an organisation.
//
// Two words, not five: GitHub's organisation membership is admin or member, and
// inventing the three levels in between to match GitLab's would be reporting a
// distinction the platform does not make.
//
// A membership that cannot be read is not an error — the explorer would show
// nothing rather than a column short, which is the wrong trade (§3.6 step 2).
func (f *Forge) orgRole(ctx context.Context, org, login string) string {
	membership, _, err := f.client.Organizations.GetOrgMembership(ctx, login, org)
	if err != nil {
		return ""
	}
	if membership.GetRole() == "admin" {
		return "Owner"
	}
	return "Member"
}

// lastWorkflowStatus is the most recent Actions run, translated into the
// vocabulary forge.CIStatus* declares.
//
// A run still in flight has no conclusion, so its *status* is used instead —
// otherwise a repository whose build is running would read as having no CI at
// all. The two are different alphabets, which is why ciStatusOf takes both and
// not one string.
//
// It was called lastWorkflowConclusion and claimed to return "the same words
// the GitLab backend reports". It never did (D66): only `success` and `skipped`
// happen to be spelled the same, so `failure` reached the CI column as raw text
// truncated to `failu…` and coloured orange by the view's default branch — a
// broken build rendered as a warning, which is the one thing that column exists
// to prevent.
func (f *Forge) lastWorkflowStatus(ctx context.Context, owner, repo string) string {
	runs, _, err := f.client.Actions.ListRepositoryWorkflowRuns(ctx, owner, repo,
		&gh.ListWorkflowRunsOptions{ListOptions: gh.ListOptions{PerPage: 1, Page: 1}})
	if err != nil || runs == nil || len(runs.WorkflowRuns) == 0 {
		return ""
	}

	run := runs.WorkflowRuns[0]
	return ciStatusOf(run.GetConclusion(), run.GetStatus())
}

// ciStatusOf translates one Actions run onto forge's vocabulary.
//
// The conclusion is read first and the status only when there is none: a
// completed run carries both, and its `completed` status says nothing a reader
// wants — which is precisely why `completed` appears in neither table below.
//
// **An unrecognised value returns the empty string**, not itself. That is what
// forge.Repository.CIStatus documents for a value the backend has no equivalent
// for, and it is the difference between an empty cell and six characters of
// GitHub's internal spelling. Returning the raw word was the defect.
func ciStatusOf(conclusion, status string) string {
	if conclusion != "" {
		return ciConclusions[conclusion]
	}
	return ciRunStates[status]
}

// ciConclusions maps a finished run. Four of GitHub's nine outcomes have no
// counterpart and are folded rather than dropped, each on its own argument:
//
//   - `timed_out` and `startup_failure` are **failures**. GitLab has no separate
//     status for either — a job it kills on timeout ends `failed` — so folding
//     them is reporting what GitLab would have reported, not losing detail.
//   - `action_required` is a run waiting for someone to approve it, which is
//     exactly what GitLab calls `manual`.
//   - `neutral` and `stale` are the grey outcomes: ran without a verdict, and
//     superseded before finishing. GitHub renders both the way it renders
//     `skipped`, and `skipped` is the only grey this vocabulary has.
var ciConclusions = map[string]string{
	"success":         forge.CIStatusSuccess,
	"failure":         forge.CIStatusFailed,
	"timed_out":       forge.CIStatusFailed,
	"startup_failure": forge.CIStatusFailed,
	"cancelled":       forge.CIStatusCanceled, // GitHub spells it with two l's
	"action_required": forge.CIStatusManual,
	"skipped":         forge.CIStatusSkipped,
	"neutral":         forge.CIStatusSkipped,
	"stale":           forge.CIStatusSkipped,
}

// ciRunStates maps a run that has not finished. GitLab separates `pending` from
// `created`, `preparing` and `waiting_for_resource`; GitHub's four pre-run
// states all mean the same thing to a reader — it has not started — so they
// collapse onto the one word the CI column already draws a clock for.
var ciRunStates = map[string]string{
	"in_progress": forge.CIStatusRunning,
	"queued":      forge.CIStatusPending,
	"requested":   forge.CIStatusPending,
	"waiting":     forge.CIStatusPending,
	"pending":     forge.CIStatusPending,
}

// splitPath cuts an owner/repo identifier.
//
// GitHub addresses a repository by its two halves in every write call, and this
// is the one place that knows the identifier has halves at all — outside this
// package it is opaque.
func splitPath(id string) (owner, repo string, ok bool) {
	owner, repo, ok = strings.Cut(id, "/")
	return owner, repo, ok && owner != "" && repo != ""
}

func firstNonEmpty(values ...string) string {
	for _, v := range values {
		if v != "" {
			return v
		}
	}
	return ""
}

package github

import (
	"context"
	"errors"
	"fmt"

	gh "github.com/google/go-github/v68/github"

	"github.com/anthnel/devdesk/internal/forge"
)

// errNoOrgAPI is what CreateNamespace and DeleteNamespace return.
//
// GitHub has no REST endpoint for either: an organisation is created and
// deleted from the web, and no token scope changes that. The interface expects
// a backend to refuse what it cannot express rather than to do something
// adjacent and report success — the alternative here would be creating a
// repository under the user's own account and calling it an organisation.
var errNoOrgAPI = errors.New("GitHub organizations are created and deleted from the web, not through the API")

// errNoPermanentDelete is what a permanent delete returns.
//
// GitHub deletes at once and has no grace period, so there is nothing to
// bypass. Deleting normally and reporting success would tell the user a
// distinction was honoured when the platform does not make one — and
// Shape.PermanentDelete is false precisely so the checkbox never gets offered.
var errNoPermanentDelete = errors.New("GitHub deletes immediately; there is no grace period to bypass")

// CreateNamespace is refused. See errNoOrgAPI.
func (f *Forge) CreateNamespace(context.Context, forge.NewNamespace) (forge.Namespace, error) {
	return forge.Namespace{}, errNoOrgAPI
}

// DeleteNamespace is refused. See errNoOrgAPI.
func (f *Forge) DeleteNamespace(context.Context, forge.Namespace, bool) error {
	return errNoOrgAPI
}

// CreateRepository creates a repository inside an organisation.
//
// An empty NamespaceID means the user's own account, which is what go-github's
// empty `org` argument does — so the interface's "empty means the user's own
// namespace" needs no translation here.
func (f *Forge) CreateRepository(ctx context.Context, spec forge.NewRepository) (forge.Repository, error) {
	shape := f.Shape()
	if spec.Visibility != "" && !shape.AllowsVisibility(spec.Visibility) {
		return forge.Repository{}, fmt.Errorf("GitHub does not offer %q visibility", spec.Visibility)
	}

	created, _, err := f.client.Repositories.Create(ctx, spec.NamespaceID, &gh.Repository{
		Name:        gh.Ptr(spec.Slug),
		Description: gh.Ptr(spec.Description),
		Private:     gh.Ptr(spec.Visibility != "public"),
		// AutoInit is deliberately off. InitialCommit is what writes the first
		// commit, and an auto-generated README would give it a parent it does
		// not expect — the two would race to own the initial state.
		AutoInit: gh.Ptr(false),
	})
	if err != nil {
		return forge.Repository{}, err
	}

	return f.repositories(ctx, []*gh.Repository{created}, "")[0], nil
}

// InitialCommit writes the first commit of an empty repository.
//
// It is four calls rather than one per file, and that is the whole design:
// Repositories.CreateFile in a loop would produce one commit per file, so a
// three-file template would arrive as three commits — and the second would need
// the SHA the first returned, which is a chain rather than a batch.
//
// The git data API takes the whole thing at once: a blob per file, one tree, a
// commit with **no parent**, then the ref that makes it the branch. No parent
// is what makes this an *initial* commit; on a repository that already has one
// the ref creation fails, which is the honest outcome — this is not a way to
// overwrite history.
func (f *Forge) InitialCommit(ctx context.Context, repositoryID string, files []forge.FileChange) error {
	owner, repo, ok := splitPath(repositoryID)
	if !ok {
		return fmt.Errorf("not a GitHub repository: %q", repositoryID)
	}
	if len(files) == 0 {
		return nil
	}

	entries := make([]*gh.TreeEntry, 0, len(files))
	for _, file := range files {
		if file.Action == forge.FileDelete {
			// There is nothing to delete in a repository with no commits, and
			// silently dropping it would hide a template that means something
			// else than it says.
			return fmt.Errorf("an initial commit cannot delete %q", file.Path)
		}

		blob, _, err := f.client.Git.CreateBlob(ctx, owner, repo, &gh.Blob{
			Content:  gh.Ptr(file.Content),
			Encoding: gh.Ptr("utf-8"),
		})
		if err != nil {
			return fmt.Errorf("uploading %s: %w", file.Path, err)
		}

		entries = append(entries, &gh.TreeEntry{
			Path: gh.Ptr(file.Path),
			Mode: gh.Ptr("100644"),
			Type: gh.Ptr("blob"),
			SHA:  blob.SHA,
		})
	}

	// No base tree: the repository is empty, and naming one that does not exist
	// is an error rather than an empty starting point.
	tree, _, err := f.client.Git.CreateTree(ctx, owner, repo, "", entries)
	if err != nil {
		return fmt.Errorf("building the tree: %w", err)
	}

	commit, _, err := f.client.Git.CreateCommit(ctx, owner, repo, &gh.Commit{
		Message: gh.Ptr(initialCommitMessage),
		Tree:    tree,
	}, nil)
	if err != nil {
		return fmt.Errorf("creating the commit: %w", err)
	}

	_, _, err = f.client.Git.CreateRef(ctx, owner, repo, &gh.Reference{
		Ref:    gh.Ptr("refs/heads/" + defaultBranch),
		Object: &gh.GitObject{SHA: commit.SHA},
	})
	if err != nil {
		return fmt.Errorf("creating %s: %w", defaultBranch, err)
	}
	return nil
}

const (
	// initialCommitMessage is the GitLab backend's, word for word: a template
	// applied on either platform should read the same in the log.
	initialCommitMessage = "Initial commit from template"

	// defaultBranch matches what both backends create. GitHub's per-account
	// default is configurable, but a repository created here has no commits
	// yet, so nothing has chosen a branch — naming it is the only way this is
	// deterministic.
	defaultBranch = "main"
)

// DeleteRepository deletes a repository. A permanent delete is refused: see
// errNoPermanentDelete.
func (f *Forge) DeleteRepository(ctx context.Context, repo forge.Repository, permanently bool) error {
	if permanently {
		return errNoPermanentDelete
	}
	owner, name, ok := splitPath(repo.ID)
	if !ok {
		return fmt.Errorf("not a GitHub repository: %q", repo.ID)
	}
	_, err := f.client.Repositories.Delete(ctx, owner, name)
	return err
}

// DashboardStats fetches the five counters.
//
// Four of them come from the **search** API, which is what GitHub offers
// instead of GitLab's X-Total header — and which has its own, much lower rate
// limit. Each is filled only when its request succeeded; a failed one stays nil
// rather than reading as a zero the dashboard would render as "you have none"
// (D52).
func (f *Forge) DashboardStats(ctx context.Context, user forge.User) (forge.DashboardStats, error) {
	if user.Username == "" {
		return forge.DashboardStats{}, errors.New("dashboard stats: no user")
	}

	var stats forge.DashboardStats
	one := &gh.SearchOptions{ListOptions: gh.ListOptions{PerPage: 1}}

	// Total is what these are for; the single result is discarded.
	if result, _, err := f.client.Search.Issues(ctx,
		"is:open is:pr assignee:"+user.Username, one); err == nil {
		stats.AssignedChangeRequests = forge.Count(result.GetTotal())
	}

	if result, _, err := f.client.Search.Issues(ctx,
		"is:open is:pr review-requested:"+user.Username, one); err == nil {
		stats.ReviewChangeRequests = forge.Count(result.GetTotal())
	}

	if result, _, err := f.client.Search.Issues(ctx,
		"is:open is:issue assignee:"+user.Username, one); err == nil {
		stats.AssignedIssues = forge.Count(result.GetTotal())
	}

	// Repositories and organisations have no search counterpart, so they are
	// walked. Both are bounded by what one account belongs to, which is not the
	// unbounded list a search would be.
	if repos, err := listAll(func(page *gh.ListOptions) ([]*gh.Repository, *gh.Response, error) {
		return f.client.Repositories.ListByAuthenticatedUser(ctx,
			&gh.RepositoryListByAuthenticatedUserOptions{ListOptions: *page})
	}); err == nil {
		stats.Repositories = forge.Count(len(repos))
	}

	if orgs, err := listAll(func(page *gh.ListOptions) ([]*gh.Organization, *gh.Response, error) {
		return f.client.Organizations.List(ctx, "", page)
	}); err == nil {
		stats.Namespaces = forge.Count(len(orgs))
	}

	return stats, nil
}

// Package session opens a forge session and remembers its token.
//
// It is the one place that knows both backends exist, and the only reason it is
// a package of its own: internal/forge must not import a backend (a domain
// package cannot depend on its implementations), and a backend must not import
// its sibling. Something above both has to choose, and this is it.
//
// The credential store is **not** forge-shaped — Storage is keyed on a URL and
// knows nothing else — so the loading and forgetting of a token are the same
// code whichever platform the context targets. Only opening a session differs,
// and only in which constructor it calls.
package session

import (
	"context"
	"fmt"

	"github.com/anthnel/devdesk/internal/config"
	"github.com/anthnel/devdesk/internal/credentials"
	"github.com/anthnel/devdesk/internal/forge"
	githubforge "github.com/anthnel/devdesk/internal/forge/github"
	gitlabforge "github.com/anthnel/devdesk/internal/forge/gitlab"
)

// Auth opens sessions against a host and remembers their tokens.
type Auth struct {
	storage credentials.Storage
}

// NewAuth builds an Auth over a secret store. A nil store is legitimate: the
// session still opens, and nothing is remembered.
func NewAuth(storage credentials.Storage) *Auth {
	return &Auth{storage: storage}
}

// Result is a live session, plus whatever could not be saved about it.
type Result struct {
	Forge forge.Forge
	User  forge.User
	// SaveWarning is set when the session opened but the token could not be
	// stored. It is not an error: the session is valid, only its persistence
	// failed, and telling the user they are not logged in would be false.
	SaveWarning string
}

// Backend builds a client for a platform, without opening a session.
//
// The default is GitLab, matching config.applyDefaults: an unknown type has
// already been normalised by the time a context is loaded, and falling through
// to the one backend that has always existed is better than returning an error
// nothing can act on.
func Backend(forgeType, url, token string) (forge.Forge, error) {
	switch forgeType {
	case config.ForgeGitHub:
		return githubforge.New(url, token)
	default:
		return gitlabforge.New(url, token)
	}
}

// Authenticate opens a session and saves the token.
func (a *Auth) Authenticate(ctx context.Context, forgeType, url, token string) (*Result, error) {
	result, err := a.AuthenticateOnly(ctx, forgeType, url, token)
	if err != nil {
		return nil, err
	}

	if a.storage != nil {
		if err := a.storage.Save(url, token); err != nil {
			result.SaveWarning = fmt.Sprintf("The token was not saved: %v. You will have to enter it again next launch.", err)
		}
	}

	return result, nil
}

// AuthenticateOnly opens a session and writes nothing. It is the auto-login
// path, whose token already comes from the store.
func (a *Auth) AuthenticateOnly(ctx context.Context, forgeType, url, token string) (*Result, error) {
	backend, err := Backend(forgeType, url, token)
	if err != nil {
		return nil, fmt.Errorf("failed to create client: %w", err)
	}

	// CurrentUser is the connection test: authentication succeeded exactly when
	// the host answers with who the token belongs to.
	user, err := backend.CurrentUser(ctx)
	if err != nil {
		return nil, fmt.Errorf("authentication failed: %w", err)
	}

	return &Result{Forge: backend, User: user}, nil
}

// LoadCredentials reads a stored token.
//
// It takes no forge type, and that is not an oversight: the store is keyed on
// the URL, so a context that switched platform without changing host finds the
// token it already had — which is right, because it is the same host asking.
func (a *Auth) LoadCredentials(url string) (string, error) {
	if a.storage == nil {
		return "", fmt.Errorf("no storage configured")
	}
	return a.storage.Load(url)
}

// Logout forgets a stored token.
func (a *Auth) Logout(url string) error {
	if a.storage == nil {
		return nil
	}
	return a.storage.Delete(url)
}

package forge

import "github.com/anthnel/devdesk/internal/config"

// Vocabulary is what a forge is *called*, as opposed to what it can do.
//
// The distinction is §3.6's: "Group" against "Organization" is a **word**,
// while nesting depth and the visibility set are **shapes** — they change what
// the application can promise, and no wording helps with them. Shape carries
// the second; this carries the first, and neither grows conditionals for the
// other.
//
// # Per forge, not neutral
//
// A GitLab user says *group*, a GitHub user says *repository*. "Namespace" is a
// third language nobody speaks, and it makes the application read as an
// abstraction layer rather than as a tool. So every word here is the one its
// forge's own documentation uses.
//
// The field names are neutral because the *code* has to be — a view cannot
// switch on which forge it is talking to — but nothing a user reads is.
//
// # No view writes a forge's name into a string
//
// That is the rule this type exists to make checkable, and
// TestNoViewNamesAForge (internal/ui/vocabtest) walks every string literal
// under internal/ui to enforce it. A command name is not covered: it is routing
// identity, the same for both forges, and lives in internal/command.
type Vocabulary struct {
	// Name is the forge as it names itself — "GitLab", "GitHub". Capitalised:
	// it is a proper noun, and it is what titles and messages interpolate.
	Name string

	// Namespace holds repositories and, on some forges, other namespaces.
	Namespace, Namespaces string

	// Repository is one repository.
	Repository, Repositories string

	// ChangeRequest is a proposal to merge a branch.
	ChangeRequest, ChangeRequests string

	// ChangeRequestShort is the initialism — "MR", "PR". The dashboard's tree
	// nodes are eleven cells wide, so the long form does not fit and truncating
	// it would produce "Merge Req…" on one forge and "Pull Requ…" on the other.
	ChangeRequestShort string

	// TokenLabel is what the auth view calls the secret it asks for.
	TokenLabel string

	// TokenPlaceholder is an example token, shown greyed in the input until the
	// user types.
	//
	// It is a hint and never a check: DevDesk does not validate the prefix, and
	// a forge that changes its format must not turn a working token into a
	// refused one. Shaped like a real value rather than as prose, because that
	// is what a placeholder is — the prose about which prefixes exist lives in
	// TokenHelp, where there is room to name more than one.
	TokenPlaceholder string

	// TokenHelp says where to create a token and which scopes it needs. One
	// sentence, because it is rendered in a help pane beside others.
	TokenHelp string

	// ExampleURL is what the configuration view suggests as a host. The public
	// instance, because it is the only address that is the same for everyone —
	// a self-hosted example would be a hostname nobody has.
	ExampleURL string
}

// gitlabVocabulary and githubVocabulary are the two, written out rather than
// derived: every word is a decision about what that forge's users call things,
// and a rule that produced them would be a rule about English rather than about
// either product.
var (
	gitlabVocabulary = Vocabulary{
		Name:               "GitLab",
		Namespace:          "Group",
		Namespaces:         "Groups",
		Repository:         "Project",
		Repositories:       "Projects",
		ChangeRequest:      "Merge Request",
		ChangeRequests:     "Merge Requests",
		ChangeRequestShort: "MR",
		TokenLabel:         "Personal Access Token",
		TokenPlaceholder:   "glpat-…",
		TokenHelp:          "Create a token in GitLab > Settings > Access Tokens. Required scopes: api, write_repository, read_repository.",
		ExampleURL:         "https://gitlab.com",
	}

	githubVocabulary = Vocabulary{
		Name:               "GitHub",
		Namespace:          "Organization",
		Namespaces:         "Organizations",
		Repository:         "Repository",
		Repositories:       "Repositories",
		ChangeRequest:      "Pull Request",
		ChangeRequests:     "Pull Requests",
		ChangeRequestShort: "PR",
		TokenLabel:         "Personal Access Token",
		TokenPlaceholder:   "ghp_… or github_pat_…",
		TokenHelp:          "Create a token in GitHub > Settings > Developer settings > Personal access tokens. Required scopes: repo, read:org.",
		ExampleURL:         "https://github.com",
	}
)

// VocabularyFor resolves the wording for a configured forge type.
//
// It takes the **configured** type rather than a live Forge, and that is
// deliberate: the explorer's "not authenticated" screen and the auth view's own
// title both need the words before any session exists. A method on Forge would
// be unavailable exactly where the words are needed most.
//
// An unknown type falls back to GitLab rather than to an empty Vocabulary. A
// screen with no nouns on it is a worse failure than a screen using the wrong
// forge's nouns, and config.applyDefaults already guarantees a known value —
// this is the belt to that brace.
func VocabularyFor(forgeType string) Vocabulary {
	switch forgeType {
	case config.ForgeGitHub:
		return githubVocabulary
	default:
		return gitlabVocabulary
	}
}

package forge

// The vocabulary a backend must report in `Repository.CIStatus`.
//
// **It is GitLab's**, and the choice is historical rather than principled:
// GitLab was the only backend when the field was added, so `lastPipelineStatus`
// returned the API's own word and the explorer's CI column switched on it. By
// the time GitHub arrived the words were already load-bearing in the view.
//
// Keeping it was still the right call. GitLab's list is the larger of the two —
// eleven values against GitHub's nine, and it separates "queued" from "not
// started" in a way GitHub does not — so translating GitHub onto it loses less
// than the reverse would. And a third backend translating onto a list that
// belongs to one of the other two is no worse than translating onto a list
// invented here.
//
// What was **not** right is that the promise was only ever a doc comment. The
// GitHub backend returned GitHub's own words for six years' worth of values
// nothing in the application had a case for, and the CI column printed them
// raw: a failed build read `failu…` in orange, which is the colour of a warning
// (§1.1 D66).
const (
	CIStatusCreated            = "created"
	CIStatusWaitingForResource = "waiting_for_resource"
	CIStatusPreparing          = "preparing"
	CIStatusPending            = "pending"
	CIStatusRunning            = "running"
	CIStatusSuccess            = "success"
	CIStatusFailed             = "failed"
	CIStatusCanceled           = "canceled"
	CIStatusSkipped            = "skipped"
	CIStatusManual             = "manual"
	CIStatusScheduled          = "scheduled"
)

// CIStatuses is every value a backend may report, and therefore every value a
// view must be able to render.
//
// It exists to be walked by a test rather than read by production code: the
// defect this file answers was a promise nobody could check, and a list a test
// can iterate is the difference between a promise and a contract. A value
// missing from a view's switch now fails a test instead of appearing on screen
// truncated to six cells.
//
// The empty string is deliberately absent. It is not a status — it means the
// decoration was not asked for, there is no pipeline, or the backend has no
// equivalent — and a view renders it as an empty cell, which is a different
// question from rendering a status.
func CIStatuses() []string {
	return []string{
		CIStatusCreated,
		CIStatusWaitingForResource,
		CIStatusPreparing,
		CIStatusPending,
		CIStatusRunning,
		CIStatusSuccess,
		CIStatusFailed,
		CIStatusCanceled,
		CIStatusSkipped,
		CIStatusManual,
		CIStatusScheduled,
	}
}

package forge

import "time"

// User is who a token belongs to.
//
// Three fields, because three are read: the username names the session in the
// header and the auth view, the name qualifies it in parentheses, and the ID is
// what the dashboard counters and the role lookups are keyed on. An avatar and
// an email are available from both forges and neither is displayed.
type User struct {
	// ID addresses the user with the backend. Opaque — see the package doc.
	ID       string
	Username string
	Name     string
}

// Namespace is a container of repositories and of other namespaces: a GitLab
// group or subgroup, a GitHub organisation.
type Namespace struct {
	// ID addresses it with the backend; Path is `group/subgroup`, the form the
	// user reads and the clone URL is built from. See the package doc.
	ID   string
	Path string
	Name string

	Visibility string
	// Role is already humanised — "Owner", "Maintainer", "Member". A backend
	// returns a word, never a number: GitLab's levels (50, 40, 30…) and
	// GitHub's (`admin`, `maintain`, `push`, `triage`, `pull`) do not align one
	// to one, so a caller translating an integer would be translating GitLab's.
	// Empty means the role was not asked for, or is not known.
	Role string

	CreatedAt *time.Time
	// WebURL opens it in a browser. It comes from the forge rather than being
	// assembled from the host and the path — a self-hosted instance under a
	// path prefix would be assembled wrong.
	WebURL string
}

// Repository is one repository: a GitLab project, a GitHub repository.
type Repository struct {
	ID   string
	Path string
	Name string

	Visibility string
	// Role, humanised. See Namespace.Role.
	Role string

	CreatedAt      *time.Time
	LastActivityAt *time.Time
	WebURL         string

	// CIStatus is the last pipeline or workflow run — "success", "failed",
	// "running"… Empty when it was not asked for, when there is none, or when
	// the backend has no equivalent.
	CIStatus string

	// DeletionScheduled says the forge has already marked it for deletion and
	// only a permanent removal remains. It is always false on a backend whose
	// Shape says PermanentDelete is false, because there is no such state
	// there — a delete is immediate.
	DeletionScheduled bool
}

// Children is what one namespace directly contains.
//
// Two slices rather than one list of a sum type: the caller does different
// things with them — the explorer decorates repositories and not namespaces,
// the clone recurses into namespaces and clones repositories — and a single
// list would have every caller switch on a kind to get back here.
type Children struct {
	Namespaces   []Namespace
	Repositories []Repository
}

// BrowseOptions is what a listing may vary. Both fields cost something, which
// is why neither is implied.
//
// It covers RootNamespaces as well as Children, because the difference the
// clone needs is the same at both levels: its walk starts from a root and pays
// for no decoration anywhere. IncludeArchived is meaningless for namespaces —
// neither forge archives one — and is ignored there rather than split into a
// second type for one field.
type BrowseOptions struct {
	// IncludeArchived lists archived repositories. Browsing passes true — the
	// explorer shows what is there — and a clone passes
	// `forge.pull.include_archived`, which is what that setting means and the
	// only place it is read.
	IncludeArchived bool

	// Decorated fills Role and CIStatus on every repository returned.
	//
	// It is optional because it is expensive and because one caller genuinely
	// does not want it: on GitLab it is two extra requests *per repository*, so
	// a two-hundred-repository group costs 400 calls for a CI badge and a role
	// that a clone never looks at. The explorer asks for it, the clone's walk
	// does not.
	Decorated bool
}

// NewNamespace is a namespace to create.
type NewNamespace struct {
	Name        string
	Slug        string
	Description string
	Visibility  string
	// ParentID is the namespace it goes under, empty for a root one. A backend
	// whose Shape cannot nest that deep refuses rather than creating it at the
	// root — a namespace silently created somewhere else is worse than an
	// error, because the user goes looking for it where they asked for it.
	ParentID string
}

// NewRepository is a repository to create.
type NewRepository struct {
	Name        string
	Slug        string
	Description string
	Visibility  string
	// NamespaceID is where it goes; empty means the user's own namespace.
	NamespaceID string
}

// FileChange is one file in an initial commit.
type FileChange struct {
	Action  FileAction
	Path    string
	Content string
}

// FileAction is what an initial commit does to a file.
type FileAction string

const (
	FileCreate FileAction = "create"
	FileUpdate FileAction = "update"
	FileDelete FileAction = "delete"
)

// CloneMethod is how a repository is cloned.
type CloneMethod string

const (
	CloneHTTPS CloneMethod = "https"
	CloneSSH   CloneMethod = "ssh"
)

// DashboardStats are the dashboard's counters.
//
// Every count is a pointer, and nil means **nobody looked** — the counters come
// from five independent requests and any of them can fail on its own. A plain
// int cannot say that: today each failure leaves a zero, and the dashboard
// renders a dim `0` that is indistinguishable from "no merge requests assigned
// to you". That is D20 in five fields, and `Sensitive *bool` in the scan caches
// is the precedent for the fix — a value that says "not known" rather than a
// zero that reads as an answer.
type DashboardStats struct {
	AssignedChangeRequests *int
	ReviewChangeRequests   *int
	AssignedIssues         *int
	Repositories           *int
	Namespaces             *int
}

// Count is a small helper for a backend filling DashboardStats: it returns a
// pointer to n, so a successful request reads `stats.AssignedIssues = Count(n)`
// and a failed one leaves the field nil by doing nothing.
func Count(n int) *int { return &n }

